#include <stdio.h>

int main() {
    int n;
    printf("Enter the given number here: ");
    scanf("%d", &n);
    if (n % 5 == 0 || n % 3 == 0) {
        if(n % 15 != 0) {
            printf("The given number is divisible by 3 or 5 not 15.");
        }else {
            printf("the number is divisible by 15.");
        }
    } else {
        printf("The given number isn't divisible by either 3 or 5");
    }
    return 0;
}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           